# rarity colour. nameHex = the quality text colour of the stack's quality index qi (qi < 0 = the item's own quality); Wynn's #AA00AA -> #CC66CC
# (the readable Mythic, RARITIES); unreadable = dflt. The *Text lists are pure: joined they are the 0.3.58 words byte for byte.
M(gvw, r"""
public static String nameHex(String id, int qi, String dflt) {
  int q = qi;
  if (q < 0) {
    try { @ITM@ it = @PKG@.Gear.item(id); q = it == null ? -1 : it.getQualityIndex(); } catch (Throwable t) { q = -1; }
  }
  String h = q < 0 ? null : qualHex(q);
  if (h == null || h.length() != 7) return dflt;
  if (h.equalsIgnoreCase("#AA00AA")) return "#CC66CC";
  return h;
}""")
M(gvw, r"""
public static @MSG@ partsMsg(String[] t, String[] c, String base) {
  @MSG@ m = @MSG@.empty();
  for (int i = 0; t != null && i < t.length; i++) {
    if (t[i] == null || t[i].length() == 0) continue;
    String h = (c == null || i >= c.length || c[i] == null) ? base : c[i];
    m.insert(@MSG@.raw(t[i]).color(h));
  }
  return m;
}""")
