COLOUR_BLOCK = r'''# ================================================================= 0.3.59 (rar3): COLOUR-CODED DESCRIPTIONS (Style Guide section 15; Skyy
# 2026-10-24 + 2026-10-18; tools/gear_0_3_59_patch.py). Every description line of ours without a <color span gets the spans; the tier tag + ' - '
# stay plain (GearView's tier line). The lists the jar checks below (G23_LANG, IWB_LANG, U28_LANG, AUG_LANG, U53_LANG ...) are rewritten the same way.
_C59 = {"set": [r for r in RARITIES if r[0] == "set"][0][2], "ut": [r for r in RARITIES if r[0] == "untiered"][0][2],
        "act": "#ffcc00", "prog": "#e8c25a", "good": "#7ee08a", "cost": "#ff7a7a", "dim": "#7f93a6"}          # ui-data: Style Guide 15 hexes
_C59.update(("rar_" + r[1], r[2]) for r in RARITIES)
assert (_C59["set"], _C59["ut"]) == ("#55FF55", "#FFAA00"), _C59
_RX59_TAG = re.compile(r"^T[0-9]+ [A-Za-z]+(?: [A-Za-z]+)* - ")
_RX59 = re.compile(
    r"(?P<set>^[A-Z][A-Za-z]*(?: [A-Z][A-Za-z]*)* (?:Bark|Harvest|Angler|Mining) [Ss]et(?= - ))"
    r"|(?P<act>Hold right-click|right-click|a swing|/identify|/smithing|tiers up on the Anvil|tier it up on the Anvil)"
    r"|(?P<prog>levels with (?:your )?(?:Mining|Foraging|Farming|Fishing)|Needs your Mining level|after your first rebirth)"
    r"|(?P<good>waters a bigger square|reaps every crop of its tier and lower)"
    r"|(?P<cost>half Farming XP)"
    r"|(?P<dim>Never sold on the Bazaar\.)"
    r"|(?P<ut>\bUntiered\b)"
    r"|(?<=to )(?P<rar>Unique|Rare|Legendary|Fabled|Mythic)(?= on the Anvil)")


def strip_colour59(t):
    """the text without its colour spans (the build check + the harness compare this with the 0.3.58 text)"""
    return re.sub(r"</?color[^>]*>", "", t)


def _colour59(m):
    k = m.lastgroup
    hx = _C59["rar_" + m.group(k)] if k == "rar" else _C59[k]
    return '<color is="%s">%s</color>' % (hx, m.group(k))


def colour59(text):
    """one description: the tag + ' - ' kept plain, the body colour-coded; a text that already has a span is returned as is"""
    if "<color is=" in text:
        return text
    m = _RX59_TAG.match(text)
    cut = m.end() if m else 0
    return text[:cut] + _RX59.sub(_colour59, text[cut:])


def colour59_line(line):
    """a server.lang line: an items.<id>.description line gets colour59, every other line is returned unchanged"""
    k, sep, v = line.partition("=")
    if not sep or not k.strip().startswith("items.") or not k.strip().endswith(".description"):
        return line
    lead = len(v) - len(v.lstrip(" "))
    return k + sep + v[:lead] + colour59(v[lead:])


_L58 = EXTRA["Server/Languages/en-US/server.lang"]
_L59 = "\n".join(colour59_line(_l) for _l in _L58.split("\n"))
for _nm in ("LANG", "BAG_LANG", "SIG_LANG", "CAN_LANG", "IWB_LANG", "UT_LANG", "U28_LANG", "U53_LANG", "G23_LANG", "GA2_LANG", "ZM_LANG", "AUG_LANG"):
    globals()[_nm] = [colour59_line(_x) for _x in globals()[_nm]]          # the post-build checks look for these exact lines
_k58 = [_l.split("=", 1)[0].strip() for _l in _L58.split("\n") if "=" in _l]
_d58 = dict((_l.split("=", 1)[0].strip(), _l.split("=", 1)[1].strip()) for _l in _L58.split("\n") if "=" in _l)
_d59 = dict((_l.split("=", 1)[0].strip(), _l.split("=", 1)[1].strip()) for _l in _L59.split("\n") if "=" in _l)
_ch59 = sorted(_k for _k in _d58 if _d58[_k] != _d59[_k])
assert len(_k58) == len(set(_k58)) == len(_d59), "0.3.59: each lang key once"
assert all(_k.startswith("items.") and _k.endswith(".description") for _k in _ch59), "0.3.59: only description lines change"
assert all(strip_colour59(_d59[_k]) == _d58[_k] for _k in _ch59), "0.3.59: every recoloured text keeps its words"
assert all(re.fullmatch(r'(?:[^<]|<color is="#[0-9A-Fa-f]{6}">[^<]*</color>)*', _d59[_k]) and _d59[_k].isascii() for _k in _ch59), "0.3.59: spans balanced / not nested, ASCII"
assert not [_k for _k in _d59 if _k.endswith(".description") and "<color is=" not in _d59[_k]], "0.3.59: every description is colour coded"
assert all(_RX59_TAG.match(_d58[_k]) is None or _d59[_k].startswith(_RX59_TAG.match(_d58[_k]).group(0)) for _k in _ch59), "0.3.59: the tier tag stays first and plain"
assert not [_k for _k in _d59 if _k.endswith(".name") and "<" in _d59[_k]], "0.3.59: names stay plain"
EXTRA["Server/Languages/en-US/server.lang"] = _L59
print("0.3.59 colour pass: %d description lines colour coded (Style Guide 15), %d lang keys" % (len(_ch59), len(_d59)))
'''
